mapper.select:
select t.FINPROD_MARKET_ID id, t.FINPROD_MARKET_ID text, fpt.TYPE_9, fpa.WIND_CODE from FIN_PRODUCT t left join FIN_PRODUCT_TYPE fpt on t.FINPROD_ID = fpt.FINPROD_ID left join FIN_PRODUCT_ADD fpa on t.FINPROD_ID = fpa.FINPROD_ID
t.TRADE_MARKET = '12' and t.FINPROD_TYPE2='F36'
and t.FINPROD_MARKET_ID = #{futuresId}
and t.FINPROD_MARKET_ID = #{initValue}
AND (t.finprod_market_id like concat('%',concat(#{search},'%')) OR t.finprod_name like concat('%',concat(#{search},'%')))

select fpa.WIND_CODE id, fpa.WIND_CODE text from FIN_PRODUCT t left join FIN_PRODUCT_ADD fpa on t.FINPROD_ID = fpa.FINPROD_ID
t.TRADE_MARKET = '12' and t.FINPROD_TYPE2='F36'
and fpa.WIND_CODE = #{windCode}
and fpa.WIND_CODE = #{initValue}
AND fpa.WIND_CODE like concat('%',concat(#{search},'%'))

select FUTURES_ID futuresId, TRADE_DATE tradeDate, WIND_CODE windCode, PRESETTLE_PRICE preSettlePrice, OPEN_PRICE openPrice, HIGH_PRICE highPrice, LOW_PRICE lowPrice, CLOSE_PRICE closePrice, SETTLE_PRICE settlePrice from MST_FUTURES_PRICE
and FUTURES_ID = #{futuresId,jdbcType=VARCHAR}
and WIND_CODE = #{windCode,jdbcType=VARCHAR}
AND TRADE_DATE >= TO_DATE(#{tradeDateStart,jdbcType=VARCHAR},'YYYY-MM-DD')
AND TRADE_DATE <= TO_DATE(#{tradeDateEnd,jdbcType=VARCHAR},'YYYY-MM-DD')

mapper.delete:
delete from MST_FUTURES_PRICE
where FUTURES_ID = #{futuresId,jdbcType=VARCHAR}
    and TRADE_DATE = #{tradeDate,jdbcType=DATE}
